mapper.insert:
insert into ai_product_asset_images (
    id, product_asset_id, user_id, task_id, image_role, oss_bucket, oss_object_key, oss_url,
    mime_type, file_size, width, height, sort_order, analysis_role, created_at, updated_at
) values (
    cast(#{id} as uuid), cast(#{productAssetId} as uuid), #{userId}, cast(#{taskId} as uuid),
    #{imageRole}, #{ossBucket}, #{ossObjectKey}, #{ossUrl}, #{mimeType}, #{fileSize},
    #{width}, #{height}, #{sortOrder}, #{analysisRole}, #{createdAt}, #{updatedAt}
)

mapper.delete:
